[CmdletBinding()]
param([Parameter(Mandatory)][string]$RecordPath,[string]$OutputPath,[switch]$AllowNonCompliant)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
function Get-Value{param([object]$Object,[string]$Name)if($null-eq$Object){return $null};$p=$Object.PSObject.Properties[$Name];if($null-eq$p){return $null};$p.Value}
function Test-Present{param([object]$Value)if($null-eq$Value){return $false};if($Value-is[string]){return -not[string]::IsNullOrWhiteSpace($Value)};if($Value-is[System.Collections.IEnumerable]-and$Value-isnot[string]){return @($Value).Count-gt 0};return $true}
function Add-Failure{param([System.Collections.Generic.List[object]]$Failures,[string]$Field,[string]$Reason)$Failures.Add([pscustomobject]@{control='provenance_reconciliation_forward_propagation';field=$Field;disposition='BLOCK';reason=$Reason})}
if(-not(Test-Path -LiteralPath $RecordPath)){throw "Governance record not found: $RecordPath"}
$record=Get-Content -LiteralPath $RecordPath -Raw|ConvertFrom-Json -Depth 100
$failures=[System.Collections.Generic.List[object]]::new();$reopeningTrigger=[string](Get-Value $record 'reopeningTrigger')
if((Test-Present $reopeningTrigger)-and$reopeningTrigger-ne'none'){$r=Get-Value $record 'reconciliation';if($null-eq$r){Add-Failure $failures 'reconciliation' 'A reopened record is not closure. Reconciliation evidence is required.'}else{if((Get-Value $r 'provenancePreserved')-ne$true){Add-Failure $failures 'reconciliation.provenancePreserved' 'Time does not erase provenance.'};foreach($field in @('priorCanonicalState','newEvidence','validationResult','mechanism','propagationMap','auditReceipt')){if(-not(Test-Present(Get-Value $r $field))){Add-Failure $failures "reconciliation.$field" 'Required reconciliation evidence is missing.'}};$findingStatus=[string](Get-Value $r 'findingStatus');if(@('unvalidated','validated')-notcontains$findingStatus){Add-Failure $failures 'reconciliation.findingStatus' 'Finding status must be unvalidated or validated.'};if($findingStatus-eq'validated'){if((Get-Value $r 'propagationComplete')-ne$true){Add-Failure $failures 'reconciliation.propagationComplete' 'Validated finding propagation is incomplete.'};$disposition=[string](Get-Value $r 'mechanismDisposition');if(@('corrected','constrained','replaced','residual_risk_accepted')-notcontains$disposition){Add-Failure $failures 'reconciliation.mechanismDisposition' 'Validated finding requires corrected, constrained, replaced, or residual_risk_accepted disposition.'};if($disposition-eq'residual_risk_accepted'){$risk=Get-Value $r 'residualRiskAcceptance';if($null-eq$risk){Add-Failure $failures 'reconciliation.residualRiskAcceptance' 'Residual risk acceptance requires an auditable authority record.'}else{foreach($field in @('authority','authorityScope','rationale','evidenceBasis','affectedCostBearers','effectiveDate','reviewConditions','auditReceipt')){if(-not(Test-Present(Get-Value $risk $field))){Add-Failure $failures "reconciliation.residualRiskAcceptance.$field" 'Residual risk acceptance is incomplete.'}}}}}}}
$result=[ordered]@{schemaVersion='1.0.0';gate='JPV-GOV-006-DOWNSTREAM';status=$(if($failures.Count-eq0){'COMPLIANT'}else{'BLOCK'});compliant=($failures.Count-eq0);evaluatedAt=(Get-Date).ToUniversalTime().ToString('o');failures=@($failures)};$json=$result|ConvertTo-Json -Depth 30;if($OutputPath){$parent=Split-Path -Parent $OutputPath;if($parent){New-Item -ItemType Directory -Force -Path $parent|Out-Null};Set-Content -LiteralPath $OutputPath -Value $json -Encoding utf8};$json;if(-not$result.compliant-and-not$AllowNonCompliant){exit 42};exit 0